const crypto = require('crypto');
const body = JSON.stringify($json.body);
const sig = $json.headers['x-razorpay-signature'];
const expected = crypto.createHmac('sha256', $env.RAZORPAY_WEBHOOK_SECRET).update(body).digest('hex');
if (sig !== expected) throw new Error('Bad Razorpay signature');
const p = $json.body.payload.payment.entity;
return [{ json: {
  payment_id: p.id, amount_inr: p.amount / 100, paid_at: new Date(p.created_at * 1000).toISOString(),
  kind: p.notes?.kind,                    // 'workshop' or 'invoice', set on the payment link
  workshop_id: p.notes?.workshop_id, invoice_id: p.notes?.invoice_id, lead_id: p.notes?.lead_id || null,
}}];

